import{_ as i,o as e,c as l,a3 as t}from"./chunks/framework.D4-ViStF.js";const u=JSON.parse('{"title":"义理","description":"易学义理一脉——以卦爻辞与十翼为宗，重哲理、心性与人事，是「不占而明」的读易路线。","frontmatter":{"title":"义理","description":"易学义理一脉——以卦爻辞与十翼为宗，重哲理、心性与人事，是「不占而明」的读易路线。"},"headers":[],"relativePath":"yijing/yi-li/index.md","filePath":"yijing/yi-li/index.md","lastUpdated":1787730063000}'),r={name:"yijing/yi-li/index.md"};function o(n,a,d,s,h,c){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="义理" tabindex="-1">义理 <a class="header-anchor" href="#义理" aria-label="Permalink to &quot;义理&quot;">​</a></h1><p>「义理」是易学两大传统之一，与「卜筮」相对：不把《易》当作占断工具，而当作讲<strong>变化之理、立身处世</strong>的哲学经典。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>义理一脉的读法是：从卦爻辞与《易传》里，读出关于天道、人事、得失、进退的道理，重在「明理」而非「占断」。</p><p>代表脉络：</p><ul><li>王弼扫象，以《老子》解《易》，开义理新风</li><li>程颐《伊川易传》，以儒理贯穿六十四卦</li><li>朱熹「《易》本卜筮之书」，却在义理上集大成</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p>对现代读者，义理是最「可进入」的一条路：不需要先学起卦、装卦，就能直接从卦辞与爻辞里获得关于处境与选择的启发。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><p>本板块当前是规划层，尚未展开正文。建议顺序：</p><ol><li>先读十翼，尤其是《系辞传》，建立义理的语言</li><li>再回到六十四卦，逐卦读「卦辞—爻辞—彖—象」</li><li>最后与「卜筮」对照，看清两派如何同源而异路</li></ol><h2 id="规划状态" tabindex="-1">规划状态 <a class="header-anchor" href="#规划状态" aria-label="Permalink to &quot;规划状态&quot;">​</a></h2><ul><li>[ ] 义理总导读（本页展开）</li><li>[ ] 义理派人物与流派索引（王弼 / 程颐 / 朱熹等）</li><li>[ ] 「正易心法」等心法类文本（待归入）</li><li>[ ] 逐卦义理解读笔记</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>与「卜筮」对照：义理明理，卜筮尚占，二者同出于《易》</li><li>与「孔子十翼」对照：义理一脉以十翼为宗</li></ul>',15)])])}const _=i(r,[["render",o]]);export{u as __pageData,_ as default};
